drop table PTL_POSITION_SCENE;
CREATE TABLE
    PTL_POSITION_SCENE
    (
        SCENE_ID VARCHAR2(50) NOT NULL,
        SCENE_NUMBER VARCHAR2(50),
        TRADE_MARKET VARCHAR2(50),
        PS VARCHAR2(50),
        WORKFLOW_STATUS VARCHAR2(50),
        BUSINESS_TYPE VARCHAR2(50),
        OPERATION_TYPE VARCHAR2(50),
        TRADE_TYPE VARCHAR2(50),
        IS_ENTRUST_ID VARCHAR2(50),
        IS_FINISH VARCHAR2(50),
        DYNAMIC_CONDITION VARCHAR2(200),
        SCENE_EXPLAIN VARCHAR2(200),
        CONSTRAINT PK_PTL_POSITION_SCENE PRIMARY KEY (SCENE_ID)
    );
COMMENT ON TABLE PTL_POSITION_SCENE
IS
    '流水生成场景表';
COMMENT ON COLUMN PTL_POSITION_SCENE.SCENE_ID
IS
    '场景Id';
COMMENT ON COLUMN PTL_POSITION_SCENE.SCENE_NUMBER
IS
    '序号';
COMMENT ON COLUMN PTL_POSITION_SCENE.TRADE_MARKET
IS
    '交易场所';
COMMENT ON COLUMN PTL_POSITION_SCENE.PS
IS
    '交易方向';
COMMENT ON COLUMN PTL_POSITION_SCENE.WORKFLOW_STATUS
IS
    '交易状态';
COMMENT ON COLUMN PTL_POSITION_SCENE.BUSINESS_TYPE
IS
    '业务类型';
COMMENT ON COLUMN PTL_POSITION_SCENE.OPERATION_TYPE
IS
    '操作类型：NEW新建,BACK退回撤回,REVOKE撤销';
COMMENT ON COLUMN PTL_POSITION_SCENE.TRADE_TYPE
IS
    '交易类型:01指令，02交易';
COMMENT ON COLUMN PTL_POSITION_SCENE.IS_ENTRUST_ID
IS
    '有无指令编号';
COMMENT ON COLUMN PTL_POSITION_SCENE.IS_FINISH
IS
    '是否指令完成';
COMMENT ON COLUMN PTL_POSITION_SCENE.DYNAMIC_CONDITION
IS
    '动态参数';
COMMENT ON COLUMN PTL_POSITION_SCENE.SCENE_EXPLAIN
IS
    '场景说明';

drop table PTL_POSITION_FLOW_CFG;
CREATE TABLE
    PTL_POSITION_FLOW_CFG
    (
        SCENE_ID VARCHAR2(50) NOT NULL,
        CFG_NUMBER VARCHAR2(50) NOT NULL,
        FLOW_TYPE VARCHAR2(50),
        PROCESS_TYPE VARCHAR2(50),
        CLASS_METHOD VARCHAR2(50),
        PROCESS_CONFIG VARCHAR2(50),
        PARAMETER_CONFIG VARCHAR2(500),
        CONFIG_EXPLAIN VARCHAR2(200),
        CONSTRAINT PK_PTL_POSITION_FLOW_CFG PRIMARY KEY (SCENE_ID, CFG_NUMBER)
    );
COMMENT ON TABLE PTL_POSITION_FLOW_CFG
IS
    '流水配置表';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.SCENE_ID
IS
    '场景Id';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.CFG_NUMBER
IS
    '序号';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.FLOW_TYPE
IS
    '流水类型';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.PROCESS_TYPE
IS
    '处理类型';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.CLASS_METHOD
IS
    '类名和方法';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.PROCESS_CONFIG
IS
    '处理配置';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.PARAMETER_CONFIG
IS
    '参数设置';
COMMENT ON COLUMN PTL_POSITION_FLOW_CFG.CONFIG_EXPLAIN
IS
    '配置说明';


--场景配置
DELETE FROM PTL_POSITION_SCENE T;



--场景对应处理明细配置
--指令
DELETE FROM PTL_POSITION_FLOW_CFG T ;

